import{_ as p,o,c as t,a5 as a}from"./chunks/framework.BPFk9-tb.js";const u=JSON.parse('{"title":"写作课作业-075","description":"","frontmatter":{"date":"2020-10-02T23:02:03","title":"写作课作业-075","categories":["写作","作业","微信互联网平民创业"],"tags":["写作","作业","微信互联网平民创业"]},"headers":[],"relativePath":"posts/homework/075.md","filePath":"posts/homework/075.md"}'),c={name:"posts/homework/075.md"};function s(r,e,_,l,n,i){return o(),t("div",null,[...e[0]||(e[0]=[a("<blockquote><p>10.2写作作业：《微信互联网平民创业》之《7.最基本的决策方法是什么？》</p></blockquote><blockquote><p>“以终为始”的思考方式，该思考方式背后的逻辑是“长期价值”。</p></blockquote><blockquote><p>这个单子可以很⻓很⻓...... 每一个问题都值得认真思考。不停地罗列，不停地琢磨，不 停认真记录答案，不停地改进答案...... 如此这般，若是你竟然没有任何进步，那还真的是⻅⻤了吧?</p></blockquote><p>看到一个思考的差距，线性思维与多维度思考。</p><p>列这个清单的时候可以说是一个多维度思考的过程。如果不是看文章，不知道还需要思考这些内容，可能后面即使做了也是大概率的做不好。自己想得最多的是“我要学习怎样的专业知识”，然后怎么学。</p><p>就拿跑步来说，我一开始是把里程变小，跑一圈就给自己鼓鼓气还剩几圈，后来用了Keep，跑的时候有提醒最近一公里的用时，于是自己就通过调整速度来控制自己的节奏，状态好些就控制在6分多，状态不好时就控制在7分多，后面跑的时候想的是提高速度，有了改进的方向，反而更容易跑长一些。</p><p>在看极客时间，郑晔老师的《10x程序员工作法》，其中用埃隆·马斯克做了个例子。他的太空探索公司 SpaceX有一个目标是，送 100 万人上火星。</p><blockquote><p>美国政府曾经算过一笔账，把一个人送上火星，以现有技术是可实现的，需要花多少钱呢？答案是 100 亿美金。如果照此计算，实现马斯克的目标，送 100 万人上火星就要 1 万万亿。这是什么概念呢？这笔钱相当于美国 500 年的 GDP，实在太贵了，贵到连美国政府都无法负担。</p><p>马斯克怎么解决这个问题呢？他的目标变了，他准备把人均费用降到 50 万美元，也就是一个想移民的人，把地球房子卖了能够凑出的钱。原来需要 100 亿美金，现在要降到 50 万美金，需要降低 2 万倍。</p><p>当然，降低 2 万倍依然是一个听起来很遥远的目标。所以，我们关注的重点来了：马斯克的第二步是，把 2 万分解成 20×10×100。这是一道简单的数学题，也是马斯克三个重点的努力方向。</p><p>先看“20”：现在的火星飞船一次只能承载 5 个人，马斯克的打算是，把火箭造大一点，一次坐 100 人，这样，就等于把成本降低 20 倍。如果你关注新闻的话，会发现 SpaceX 确实在进行这方面的尝试。</p><p>再来看“10”：马斯克认为自己是私营公司，效率高，成本可以降到十分之一。他们也正在向这个方向努力，SpaceX 的成本目前已经降到了同行的五分之一。</p><p>最后的“100”是什么呢？就是回收可重复使用的火箭。如果这个目标能实现，发射火箭的成本就只是燃料成本了。这也就是我们频频看到的 SpaceX 试飞火箭新闻的原因。</p></blockquote>",8)])])}const d=p(c,[["render",s]]);export{u as __pageData,d as default};
